const r = $input.first().json.body || {};
const liste = Array.isArray(r.controles) ? r.controles : [];
const ko = liste.filter((c) => c.statut === 'ko');
const alertes = liste.filter((c) => c.statut === 'alerte');
const score = Number(r.score);
const degrade = Boolean(r.bloquant_ko) || score < 90;
const changement = r.changement !== false;
const lundi = $now.setZone('Europe/Paris').weekday === 1;
const alerter = degrade && (changement || lundi);
const jour = String(r.jour || '');
const court = (d) => (typeof d === 'string' && d.length === 10 ? d.slice(8, 10) + '/' + d.slice(5, 7) : String(d || ''));
const jourCourt = court(jour);
const flux = (c) => (c.nb_lignes_30j === null || c.nb_lignes_30j === undefined ? 'flux non mesuré' : c.nb_lignes_30j + ' née(s) dans les 30 jours');
const detail = (c) => c.nb_lignes + ' ligne(s), ' + flux(c) + (c.agences_texte ? ', ' + c.agences_texte : '');
const nomme = (l) => l.map((c) => c.controle + ' ' + c.libelle + ' (' + detail(c) + ')').join(', ');
const motif = !degrade ? '' : alerter ? (changement ? 'Un contrôle au moins a changé depuis ' + (r.jour_precedent ? 'le ' + court(r.jour_precedent) : 'la veille') + '.' : 'Point du lundi : résultat inchangé depuis la veille.') : 'Résultat inchangé depuis la veille : pas d\'email.';
const message = 'score ' + score + '/100 au ' + jourCourt + ', ' + ko.length + ' contrôle(s) bloquant(s) KO' + (ko.length ? ' : ' + ko.map((c) => c.controle).join(', ') : '') + ', ' + alertes.length + ' alerte(s)' + (alertes.length ? ' : ' + alertes.map((c) => c.controle).join(', ') : '') + (alerter ? ', email envoyé' + (changement ? '' : ' (point du lundi)') : degrade ? ', inchangé depuis la veille, pas d\'email' : '');
const lignes = liste.map((c) => '- ' + c.controle + ' ' + c.libelle + ' : ' + (c.statut === 'ok' ? 'ok' : c.statut.toUpperCase() + ', ' + detail(c)) + (c.bloquant ? ' (bloquant)' : ''));
const texte = 'Contrôles de cohérence du ' + jourCourt + ' : score ' + score + '/100.\n' + (motif ? motif + '\n' : '') + 'Le score compte les anomalies depuis leur apparition (stock) ; le flux dit si elles continuent d\'arriver.\n\n' + (ko.length ? 'Contrôles bloquants en échec : ' + nomme(ko) + '.\n' : '') + (alertes.length ? 'Alertes : ' + nomme(alertes) + '.\n' : '') + '\nDétail :\n' + lignes.join('\n') + '\n\nÉcran Qualité : https://buta.lyfh.fr/qualite\nDémonstrateur personnel, données d\'activité simulées.';
const sujet = 'Buta.Lyfh : contrôles du ' + jourCourt + ', score ' + score + '/100' + (ko.length ? ', ' + ko.length + ' bloquant(s) KO' : '') + (alerter && !changement ? ' (point du lundi)' : '');
return [{ json: { jour, score, alerter, changement, statut: alerter ? 'alerte' : 'ok', message: message.slice(0, 300), sujet, texte, nb_ko: ko.length, nb_alertes: alertes.length, nb_controles: liste.length } }];
